// tests/helpers/paths-817-corpus.js — TASK 817 (brief: "node: the worker and the main thread produce identical derivations (corpus)"; BYTE IDENTITY: "every exported file
// identical to before (the 909 opfirst corpus): only WHEN paths are computed changes, never what"). Every case of the operation-first corpus (tests/fixtures/opfirst/,
// the same cases and frozen baseline tests/helpers/opfirst-corpus.js reads) is loaded through applyShaperDoc, then, with the paths generated by a REAL worker thread
// running the page's paths worker (tests/helpers/node-paths-worker.js: apps/shaper/src/paths-worker.js, structured clone between the threads):
//   1. every plan membership: the worker's generated derivation (op-paths.js lookup: op-derive.js deriveItem in the worker, copied across) = the main thread's own
//      deriveItem of the same input, as key-sorted JSON (functions dropped: a cut's `sweep` stays in the worker);
//   2. the file made in the background (export-payload.js exportFileInBackground: svgOf in the worker) = the BASELINE frozen before S1 (its md5 `a`), which the main
//      thread's file equals (tests/opfirst-corpus-<n>-node); its preview copy too (without data-op: `b`) and the Paths view's bit-centre travel computed in the worker
//      (`c`); the first cases of each part also against the main thread's own files directly.
// Split in parts like the corpus test (every parts-th case) so each file stays within the gate's per-file time.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import zlib from 'node:zlib';
import './node-app.js';
import { loadCase, md5, canonical } from './opfirst-measure.js';
import { nodeWorkerPort } from './node-paths-worker.js';
import { applyShaperDoc } from '../../apps/shaper/src/shaper-doc.js';
import { planMemberItems, pathsInputOf, pathsCtx, loopsWithPolygons, planOwnedLoops } from '../../apps/shaper/src/cut-plan.js';
import { exportFileOf, exportFileInBackground, bitCentrePaths } from '../../apps/shaper/src/export-payload.js';
import { deriveItem } from '../../apps/shaper/src/op-derive.js';
import { setPathsPort, localPort, lookup, idle } from '../../apps/shaper/src/op-paths.js';

const DIR = new URL('../fixtures/opfirst/', import.meta.url);
const cases = JSON.parse(fs.readFileSync(new URL('cases.json', DIR), 'utf8'));
const pool = JSON.parse(zlib.gunzipSync(fs.readFileSync(new URL('pool.json.gz', DIR))));
const baseline = JSON.parse(fs.readFileSync(new URL('baseline.json', DIR), 'utf8')).cases;
const expand = (c) => { // as tests/helpers/opfirst-corpus.js expands a case (its levels / STL from the pool)
  const sidecar = JSON.parse(JSON.stringify(c.sidecar));
  for (const e of sidecar.cutPlan || []) if (e && e[1] && e[1].levels && e[1].levels.$levels) e[1].levels = pool.levels[e[1].levels.$levels];
  if (sidecar.stl && sidecar.stl.$stl) sidecar.stl = pool.stl[sidecar.stl.$stl];
  return { geometry: pool.geometry[c.geometry], sidecar, settings: c.settings };
};
const noOpIds = (svg) => svg.replace(/ data-op="[^"]*"/g, '');

export async function runPathsCorpus(part, parts) {
  let checks = 0, items = 0, files = 0;
  const eq = (a, b, m) => { assert.deepStrictEqual(a, b, m); checks++; };
  setPathsPort(nodeWorkerPort());
  try {
    for (const c of cases.filter((x, n) => n % parts === part)) {
      const x = expand(c);
      const state = loadCase(x);
      applyShaperDoc(x.sidecar, state);
      const { loops, loopPolys } = loopsWithPolygons(state);
      const owned = planOwnedLoops(state, loops, loopPolys);
      const ctx = pathsCtx(state, { loops, loopPolys, owned });
      const inputs = planMemberItems().map((it) => ({ it, input: pathsInputOf(it.planKey, it.rec) })).filter((q) => q.input);
      for (const { input } of inputs) lookup(ctx, input.target, input.rec); // asked for: the worker thread generates them
      await idle();
      for (const { it, input } of inputs) {
        const gen = lookup(ctx, input.target, input.rec, { request: false });
        assert.ok(gen !== undefined, `${c.name} ${it.id}: generated`);
        eq(canonical(gen), canonical(deriveItem(input.target, input.rec, state, loops, loopPolys, owned)), `${c.name} ${it.id}: the worker's derivation = the main thread's`);
        items++;
      }
      // the files: made in the worker, compared with the baseline the main thread's files are compared with (tests/opfirst-corpus-<n>-node: main = baseline), so
      // worker = baseline = main without deriving them a second time here (the gate's per-file time)
      const bg = await exportFileInBackground(state);
      if (!bg) continue;
      const base = baseline[c.name];
      eq(md5(bg.svg), base.a, `${c.name}: the file made in the worker = the baseline frozen before S1 (a)`);
      const pb = await exportFileInBackground(state, { preview: true });
      eq(md5(noOpIds(pb.svg)), base.b, `${c.name}: the preview copy made in the worker = the baseline (b)`);
      eq(md5(pb.bitPaths), base.c, `${c.name}: the Paths view's travel made in the worker = the baseline (c)`);
      if (files < 12) { // and, for the first cases of the part, against the main thread's own files directly
        eq(bg.svg, exportFileOf(state).svg, `${c.name}: the file made in the worker = the main thread's`);
        const pm = exportFileOf(state, { preview: true });
        eq([pb.svg, canonical(pb.bitPaths)], [pm.svg, canonical(bitCentrePaths(state, pm.written))], `${c.name}: the preview copy and the Paths view made in the worker = the main thread's`);
      }
      files++;
    }
  } finally { setPathsPort(localPort()); } // the worker thread is terminated
  return { checks, items, files };
}
